import type { ImageComponentData } from './../../ricos-content/index.js';
import type { CardData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { BackgroundImage } from './../../ricos-schema/next-schema/index.js';
import type { PublicCommands } from './../../ricos-types/index.js';
import type { PickMediaImageData, PublicPickMedia } from './../../_shared/media/public-pick-media.js';
import type { PmCardNode } from './../../_shared/pm-node-types.js';

type CardAttrs = PmCardNode['attrs'];

const buildBackgroundImageAttrs = ({
  componentData,
  uploadData,
}: {
  componentData: CardAttrs;
  uploadData: ImageComponentData | PickMediaImageData;
}): CardAttrs => {
  const existingBgImage: BackgroundImage | undefined = componentData.backgroundImage ?? undefined;
  return {
    ...componentData,
    backgroundImage: {
      ...existingBgImage,
      media: {
        src: 'src' in uploadData ? uploadData.src : { id: uploadData.file_name },
        width: uploadData.width,
        height: uploadData.height,
      },
      opacity: existingBgImage?.opacity ?? 100,
      scaling: existingBgImage?.scaling ?? 'COVER',
      position: existingBgImage?.position ?? 'CENTER',
    },
    loading: undefined,
  };
};

export const handleCardImageUpload = async ({
  pickImage,
  publicCommands,
  nodeId,
}: {
  pickImage: PublicPickMedia['pickImage'];
  publicCommands: PublicCommands;
  nodeId: string;
}): Promise<void> => {
  const result = await pickImage({ multiple: false });

  switch (result.type) {
    case 'ready-media': {
      const data = result.media[0] as ImageComponentData | PickMediaImageData;
      const componentData: CardAttrs = publicCommands?.getBlockComponentData(nodeId);
      const updatedData = buildBackgroundImageAttrs({ componentData, uploadData: data });

      publicCommands?.setBlock(nodeId, 'CARD', updatedData as CardData);
      return;
    }
    case 'cancel': {
      return;
    }
    default: {
      console.error('Unhandled media picker result:', result);
      return;
    }
  }
};
