import {
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_CARD_TYPE,
  TIPTAP_LAYOUT_TYPE,
} from './../ricos-content/index.js';
import type { Node as PmNode } from './../tiptap/pm/model.js';
import type { EditorState, Transaction } from './../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../tiptap/pm/state.js';
import { findWrapping } from './../tiptap/pm/transform.js';

import { CARD_DEFAULTS } from './shared-with-viewer.js';

/**
 * Build a transaction that wraps every consecutive range of non-CARD top-level
 * nodes in a CARD. Returns `null` if the doc is already fully wrapped.
 */
const buildCardWrappingTr = (state: EditorState): Transaction | null => {
  const rangesToWrap: { from: number; to: number }[] = [];
  let rangeStart: number | null = null;
  let rangeEnd: number | null = null;

  state.doc.forEach((node, pos) => {
    if (node.type.name !== TIPTAP_CARD_TYPE) {
      if (rangeStart === null) {
        rangeStart = pos;
      }
      rangeEnd = pos + node.nodeSize;
    } else if (rangeStart !== null && rangeEnd !== null) {
      rangesToWrap.push({ from: rangeStart, to: rangeEnd });
      rangeStart = null;
      rangeEnd = null;
    }
  });

  if (rangeStart !== null && rangeEnd !== null) {
    rangesToWrap.push({ from: rangeStart, to: rangeEnd });
  }

  if (rangesToWrap.length === 0) {
    return null;
  }

  const tr = state.tr;

  // Wrap in reverse order to preserve positions
  for (let i = rangesToWrap.length - 1; i >= 0; i--) {
    const { from, to } = rangesToWrap[i];
    const $from = tr.doc.resolve(from);
    const $to = tr.doc.resolve(to);
    const nodeRange = $from.blockRange($to);
    const wrapping =
      nodeRange &&
      findWrapping(nodeRange, state.schema.nodes[TIPTAP_CARD_TYPE], {
        width: CARD_DEFAULTS.width,
        height: CARD_DEFAULTS.height,
      });

    if (wrapping) {
      tr.wrap(nodeRange, wrapping);
    }
  }

  return tr;
};

/**
 * After a user deletes the LAYOUT inside a CARD_HEADER / CARD_FOOTER, PM
 * auto-fills the wrapper with a placeholder LAYOUT (no banner attr) so the
 * `LAYOUT`-only content rule is satisfied. The wrapper visually remains
 * even though its banner content is gone — confusing for the user.
 *
 * Detect those stale wrappers and remove them: a CARD_HEADER whose LAYOUT
 * lacks `banner.position === 'TOP'` (or CARD_FOOTER lacking `'BOTTOM'`) is
 * treated as a leftover and dropped from the CARD. Real headers/footers
 * always carry the matching banner attribute on their inner LAYOUT.
 */
const buildStaleWrapperCleanupTr = (state: EditorState): Transaction | null => {
  const toDelete: { from: number; to: number }[] = [];

  state.doc.descendants((node, pos) => {
    if (node.type.name !== TIPTAP_CARD_TYPE) {
      return true;
    }
    node.forEach((child, childOffset) => {
      const isHeader = child.type.name === TIPTAP_CARD_HEADER_TYPE;
      const isFooter = child.type.name === TIPTAP_CARD_FOOTER_TYPE;
      if (!isHeader && !isFooter) {
        return;
      }
      const expectedPosition = isHeader ? 'TOP' : 'BOTTOM';
      const layoutChild: PmNode | null = child.firstChild;
      const banner = layoutChild?.attrs?.banner;
      const hasBanner =
        layoutChild?.type.name === TIPTAP_LAYOUT_TYPE &&
        banner !== null &&
        (banner.position === expectedPosition || (isHeader && !banner.position));
      if (!hasBanner) {
        const wrapperStart = pos + 1 + childOffset;
        toDelete.push({ from: wrapperStart, to: wrapperStart + child.nodeSize });
      }
    });
    // Don't descend into cards — wrappers can only be direct children of CARD.
    return false;
  });

  if (toDelete.length === 0) {
    return null;
  }

  const tr = state.tr;
  // Delete in reverse so earlier positions stay valid.
  for (let i = toDelete.length - 1; i >= 0; i--) {
    tr.delete(toDelete[i].from, toDelete[i].to);
  }
  return tr;
};

export const createCardNormalizingTransactionPlugin = (): Plugin => {
  return new Plugin({
    key: new PluginKey('normalize-card'),
    appendTransaction: (_, oldState: EditorState, newState: EditorState) => {
      if (newState.doc.eq(oldState.doc)) {
        return;
      }
      // Cleanup stale wrappers first so subsequent wrap-pass sees the final
      // structural shape (and doesn't re-wrap content around dead wrappers).
      const cleanupTr = buildStaleWrapperCleanupTr(newState);
      if (cleanupTr) {
        return cleanupTr;
      }
      return buildCardWrappingTr(newState);
    },
    // The editor's initial doc may already contain unwrapped top-level nodes
    // (e.g., a paragraph + image that the converter emits without CARD).
    // `appendTransaction` only fires for *user-driven* transactions, so a
    // toolbar action triggered before any keystroke would see an unwrapped
    // doc — `findParentCardId` returns undefined and the action runs at
    // doc-level instead of inside the card. Dispatch the wrap on mount so
    // every code path observes the normalized shape.
    view(editorView) {
      const tr = buildCardWrappingTr(editorView.state);
      if (tr) {
        editorView.dispatch(tr);
      }
      return {};
    },
  });
};
