import type { PmNodeConverter, PmNodeJson } from './../pm-converters/types.js';
import { definePmNodeConverter } from './../pm-converters/types.js';
import {
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
} from './../ricos-content/index.js';
import type { CardNode, LayoutNode, Node } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

const isHeaderLayout = (node: Node): node is LayoutNode =>
  node.type === Node_Type.LAYOUT &&
  node.layoutData?.banner !== undefined &&
  (node.layoutData.banner.position === 'TOP' || !node.layoutData.banner.position);

const isFooterLayout = (node: Node): node is LayoutNode =>
  node.type === Node_Type.LAYOUT && node.layoutData?.banner?.position === 'BOTTOM';

export const cardConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.CARD],
    convert: (node: CardNode, visit) => {
      const header = node.nodes.find(isHeaderLayout);
      const footer = node.nodes.find(isFooterLayout);
      const contentNodes = node.nodes.filter(n => n !== header && n !== footer);
      const contentChildren = visit?.({ ...node, nodes: contentNodes }) ?? [];
      const [headerLayout] = header && visit ? visit({ ...node, nodes: [header] }) : [];
      const [footerLayout] = footer && visit ? visit({ ...node, nodes: [footer] }) : [];

      const pmContent: PmNodeJson[] = [];
      if (headerLayout) {
        pmContent.push({
          type: TIPTAP_CARD_HEADER_TYPE,
          content: [headerLayout],
        });
      }
      pmContent.push({
        type: TIPTAP_CARD_CONTENT_TYPE,
        // CARD_CONTENT requires at least one block — fall back to an empty paragraph
        content: contentChildren.length > 0 ? contentChildren : [{ type: 'PARAGRAPH' }],
      });
      if (footerLayout) {
        pmContent.push({
          type: TIPTAP_CARD_FOOTER_TYPE,
          content: [footerLayout],
        });
      }

      return {
        type: Node_Type.CARD,
        attrs: {
          id: node.id,
          background: node.cardData?.background ?? null,
          backgroundImage: node.cardData?.backgroundImage ?? null,
        },
        content: pmContent,
      };
    },
  },
  fromPm: {
    types: [Node_Type.CARD],
    convert: (node, visit) => {
      const { attrs = {} } = node;
      const { id, background, backgroundImage } = attrs;
      const cardChildren = node.content ?? [];

      const cardHeader = cardChildren.find(c => c.type === TIPTAP_CARD_HEADER_TYPE);
      const cardContent = cardChildren.find(c => c.type === TIPTAP_CARD_CONTENT_TYPE);
      const cardFooter = cardChildren.find(c => c.type === TIPTAP_CARD_FOOTER_TYPE);

      const headerNodes = cardHeader && visit ? visit(cardHeader) : [];
      const contentNodes = cardContent && visit ? visit(cardContent) : [];
      const footerNodes = cardFooter && visit ? visit(cardFooter) : [];

      return {
        type: Node_Type.CARD,
        id,
        cardData: {
          background: background === null ? undefined : background,
          backgroundImage: backgroundImage === null ? undefined : backgroundImage,
        },
        // Ricos schema keeps the header at the top of CARD's nodes and the
        // footer at the bottom — surrounding the regular content blocks.
        nodes: [...headerNodes, ...contentNodes, ...footerNodes],
      };
    },
  },
});

// CARD_HEADER, CARD_CONTENT, and CARD_FOOTER are PM-only structural wrappers —
// they have no Ricos schema counterpart. Their content is unwrapped by the
// parent CARD converter, so per-node `fromPmNode` callers (resolvers,
// ricos-styles, etc.) just need a no-op so the missing-converter fallback
// doesn't fire.
export const cardHeaderConverter: PmNodeConverter = {
  toPm: { types: [], convert: () => ({ type: '' }) },
  fromPm: {
    types: [TIPTAP_CARD_HEADER_TYPE],
    convert: () => undefined,
  },
};

export const cardContentConverter: PmNodeConverter = {
  toPm: { types: [], convert: () => ({ type: '' }) },
  fromPm: {
    types: [TIPTAP_CARD_CONTENT_TYPE],
    convert: () => undefined,
  },
};

export const cardFooterConverter: PmNodeConverter = {
  toPm: { types: [], convert: () => ({ type: '' }) },
  fromPm: {
    types: [TIPTAP_CARD_FOOTER_TYPE],
    convert: () => undefined,
  },
};
