import type { Background } from './../ricos-schema/next-schema/index.js';
import { resolveDocumentColorToCss } from './../_shared/theme-color-token.js';
import { getOpacityFromHex } from './../wix-rich-content-common/index.js';

const WIDTH = 900;

export const PAGE_SIZE_PRESETS = {
  FLUID: { width: WIDTH },
  A4: { width: WIDTH, height: Math.round(WIDTH * (297 / 210)) },
  LETTER: { width: WIDTH, height: Math.round(WIDTH * 1.294) },
  LEGAL: { width: WIDTH, height: Math.round(WIDTH * (14 / 8.5)) },
  SQUARE: { width: WIDTH, height: WIDTH },
} as const;

export type PageFormatName = keyof typeof PAGE_SIZE_PRESETS;

export const PAGE_FORMAT_TO_MM: Record<PageFormatName, { widthMm: number; heightMm?: number }> = {
  A4: { widthMm: 210, heightMm: 297 },
  LETTER: { widthMm: 216, heightMm: 279 },
  LEGAL: { widthMm: 216, heightMm: 356 },
  SQUARE: { widthMm: 210, heightMm: 210 },
  FLUID: { widthMm: 210 },
} as const;

export const getPageSizeByFormat = (
  format: string | undefined
): { width: number; height?: number } => {
  const key = (format?.toUpperCase() ?? 'A4') as PageFormatName;
  return PAGE_SIZE_PRESETS[key] ?? PAGE_SIZE_PRESETS.A4;
};

export const CARD_DEFAULTS = {
  width: PAGE_SIZE_PRESETS.A4.width,
  height: PAGE_SIZE_PRESETS.A4.height,
  padding: [40, 40, 40, 40],
} as const;

export const CARD_OVERFLOW_MESSAGE = 'Content exceeds page boundary';

export const isTransparentCardBackgroundColor = (color: string | undefined): boolean =>
  getOpacityFromHex(color) === 0;

export const getCardBackgroundColorCssVar = (
  background: Background | undefined,
  hasExplicitBackground: boolean
): string | undefined => {
  const backgroundColor =
    background?.type === 'COLOR' && !isTransparentCardBackgroundColor(background.color)
      ? background.color
      : undefined;
  const effectiveColor = backgroundColor ?? (hasExplicitBackground ? 'transparent' : undefined);
  return effectiveColor ? (resolveDocumentColorToCss(effectiveColor) ?? effectiveColor) : undefined;
};
