import { TIPTAP_CARD_CONTENT_TYPE } from './../ricos-content/index.js';
import { createRicosNodeExtension } from './../plugin-commons/index.js';

export const cardContentExtension = createRicosNodeExtension({
  groups: ['no-trailing-node'],
  type: 'html-node',
  name: TIPTAP_CARD_CONTENT_TYPE,
  createExtensionConfig() {
    return {
      name: this.name,
      content: 'block+',
      isolating: true,
      selectable: false,
      parseHTML() {
        return [{ tag: 'div[data-card-content]' }];
      },
      renderHTML() {
        return ['div', { 'data-card-content': 'true' }, 0];
      },
    };
  },
});
