import {
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_CARD_TYPE,
  TIPTAP_LAYOUT_TYPE,
} from './../ricos-content/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeConfig, RicosExtension, ExtensionProps } from './../ricos-types/index.js';
import { findParentNode, type Editor } from './../tiptap/core/index.js';
import { Fragment, type Node as ProseMirrorNode, type ResolvedPos } from './../tiptap/pm/model.js';
import { Selection, type Transaction } from './../tiptap/pm/state.js';
import { createRicosNodeExtension } from './../plugin-commons/index.js';
import { findNodeById } from './../tiptap-editor/helpers/index.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';

import { createCardNodeView } from './card-node-view.js';
import { createCardNormalizingTransactionPlugin } from './card-normalizing.js';
import { createCardPastePlugin } from './card-paste-plugin.js';
import { createCardsApiPlugin } from './cards-api-plugin.js';
import type { CardFormat, CardExtensionStorage } from './types.js';

type CardSplitTarget = {
  splitPos: number;
  splitDepth: number;
  orderedListStart?: number;
  listSplit?: {
    cardPos: number;
    cardContentPos: number;
    listPos: number;
    itemsBeforeSplit: number;
  };
  nestedListSplit?: {
    cardPos: number;
    cardContentPos: number;
    topListPos: number;
    topListItemIndex: number;
    targetListPos: number;
    targetListOffsetInTopItem: number;
    itemsBeforeSplit: number;
    continuationOffset: number;
    outerOrderedListStart?: number;
  };
};

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    [TIPTAP_CARD_TYPE]: {
      /**
       * Insert a card node
       */
      insertCard: () => ReturnType;
      /**
       * Add a card after a specific card index
       */
      addCardAfter: (index: number) => ReturnType;
      /**
       * Duplicate a card at a specific index
       */
      duplicateCard: (index: number) => ReturnType;
      /**
       * Delete a card at a specific index
       */
      deleteCard: (index: number) => ReturnType;
      /**
       * Move a card from one index to another.
       */
      moveCard: (fromIndex: number, toIndex: number) => ReturnType;
      /**
       * Select a card at a specific index (sets cursor at start of card)
       */
      selectCard: (index: number) => ReturnType;
      /**
       * Split the current card at the cursor position.
       * Content before the cursor stays in the current card,
       * content after the cursor moves to a new card.
       */
      splitCard: () => ReturnType;
      /**
       * Split the card at a specific document position.
       */
      splitCardAtPos: (pos: number) => ReturnType;
      /**
       * Merge the card at the given index with the next card by joining the
       * two cards' children into a single CARD. Block structure is preserved
       * as-is — the boundary between the last block of the current card and
       * the first block of the next card stays intact so the round trip with
       * splitCardAtPos at that boundary is deterministic.
       */
      mergeCardWithNext: (cardIndex: number) => ReturnType;
    };
  }
}

export const cardExtension = createRicosNodeExtension({
  name: TIPTAP_CARD_TYPE,
  groups: ['no-trailing-node', 'shortcuts-enabled'],
  type: 'html-node',
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => ({
    ...config,
    addOptions() {
      return {
        ...settings,
        _services: services,
      };
    },
  }),

  createExtensionConfig() {
    return {
      name: this.name,
      isolating: true,
      group: 'block',
      selectable: true,
      draggable: false,
      content: `${TIPTAP_CARD_HEADER_TYPE}? ${TIPTAP_CARD_CONTENT_TYPE} ${TIPTAP_CARD_FOOTER_TYPE}?`,

      addStorage(): CardExtensionStorage {
        return {
          activePageFormat: undefined,
          formats: [],
          onPageFormatChange: new Set(),
          pendingCardInsertions: [],
          onPendingCardInsertionsChange: new Set(),
        };
      },

      parseHTML() {
        return [];
      },

      renderHTML() {
        return ['div', 0];
      },

      addNodeView() {
        const services = this.options._services as TiptapAdapterServices | undefined;
        return createCardNodeView({
          renderCardHeader: this.options.renderCardHeader,
          isMobile: services?.context.isMobile,
          getBoundaryWarningPortal: this.options.getBoundaryWarningPortal,
        });
      },

      addAttributes: () => ({
        containerData: null,
        background: { default: undefined },
        backgroundImage: { default: undefined },
        loading: { default: undefined },
      }),

      addCommands() {
        return {
          insertCard:
            () =>
            ({ commands }) => {
              return commands.insertContent({
                type: TIPTAP_CARD_TYPE,
                content: [
                  {
                    type: TIPTAP_CARD_CONTENT_TYPE,
                    content: [{ type: 'PARAGRAPH' }],
                  },
                ],
              });
            },
          addCardAfter:
            (index: number) =>
            ({ editor, chain }) => {
              const { doc } = editor.state;
              let cardCount = 0;
              let insertPos: number | null = null;

              // Find the position after the card at the given index
              doc.descendants((node, pos) => {
                // Skip if we already found the target
                if (insertPos !== null) {
                  return false;
                }
                if (node.type.name === TIPTAP_CARD_TYPE) {
                  if (cardCount === index) {
                    insertPos = pos + node.nodeSize;
                    return false;
                  }
                  cardCount++;
                }
                return true;
              });

              // If no card found at index, insert at end of document
              if (insertPos === null) {
                insertPos = doc.content.size;
              }

              return chain()
                .insertContentAt(insertPos, {
                  type: TIPTAP_CARD_TYPE,
                  content: [
                    {
                      type: TIPTAP_CARD_CONTENT_TYPE,
                      content: [{ type: 'PARAGRAPH' }],
                    },
                  ],
                })
                .focus()
                .run();
            },
          duplicateCard:
            (index: number) =>
            ({ editor, chain }) => {
              const { doc } = editor.state;
              let cardCount = 0;
              let targetPos: number | null = null;
              let targetNode: ProseMirrorNode | null = null;

              // Find the card at the given index
              doc.descendants((node, pos) => {
                // Skip if we already found the target
                if (targetPos !== null) {
                  return false;
                }
                if (node.type.name === TIPTAP_CARD_TYPE) {
                  if (cardCount === index) {
                    targetPos = pos;
                    targetNode = node;
                    return false;
                  }
                  cardCount++;
                }
                return true;
              });

              if (targetPos === null || targetNode === null) {
                return false;
              }

              const insertPos = targetPos + (targetNode as ProseMirrorNode).nodeSize;
              const duplicatedContent = (targetNode as ProseMirrorNode).toJSON();

              return chain().insertContentAt(insertPos, duplicatedContent).focus().run();
            },
          deleteCard:
            (index: number) =>
            ({ editor, chain }) => {
              const { doc } = editor.state;
              let cardCount = 0;
              let targetPos: number | null = null;
              let targetNode: ProseMirrorNode | null = null;

              // Find the card at the given index
              doc.descendants((node, pos) => {
                // Skip if we already found the target
                if (targetPos !== null) {
                  return false;
                }
                if (node.type.name === TIPTAP_CARD_TYPE) {
                  if (cardCount === index) {
                    targetPos = pos;
                    targetNode = node;
                    return false;
                  }
                  cardCount++;
                }
                return true;
              });

              if (targetPos === null || targetNode === null) {
                return false;
              }

              const deleteFrom = targetPos as number;
              const deleteTo = deleteFrom + (targetNode as ProseMirrorNode).nodeSize;

              return chain().deleteRange({ from: deleteFrom, to: deleteTo }).focus().run();
            },
          moveCard:
            (fromIndex: number, toIndex: number) =>
            ({ state, tr, dispatch, editor }) => {
              if (fromIndex === toIndex) {
                return false;
              }

              const sourceCard = findCardAtIndex(state.doc, fromIndex);
              const targetCard = findCardAtIndex(state.doc, toIndex);

              if (!sourceCard || !targetCard) {
                return false;
              }

              const { node: sourceNode, pos: sourcePos } = sourceCard;
              const insertPos =
                fromIndex < toIndex
                  ? targetCard.pos + targetCard.node.nodeSize - sourceNode.nodeSize
                  : targetCard.pos;

              tr.delete(sourcePos, sourcePos + sourceNode.nodeSize);
              tr.insert(insertPos, sourceNode);

              if (dispatch) {
                dispatch(tr);
              }

              editor.commands.focus();
              return true;
            },
          selectCard:
            (index: number) =>
            ({ editor, tr, dispatch }) => {
              const { doc } = editor.state;
              let cardCount = 0;
              let targetPos: number | null = null;

              // Find the card at the given index
              doc.descendants((node, pos) => {
                // Skip if we already found the target
                if (targetPos !== null) {
                  return false;
                }
                if (node.type.name === TIPTAP_CARD_TYPE) {
                  if (cardCount === index) {
                    targetPos = pos;
                    return false;
                  }
                  cardCount++;
                }
                return true;
              });

              if (targetPos === null) {
                return false;
              }

              // Use Selection.near to find the nearest valid cursor position inside the card
              const $pos = doc.resolve(targetPos + 1);
              const selection = Selection.near($pos);

              if (dispatch) {
                tr.setSelection(selection);
                dispatch(tr);
              }

              if (!editor.isFocused) {
                editor.commands.focus();
              }
              return true;
            },
          splitCard:
            () =>
            ({ tr, dispatch }) => {
              const $from = tr.selection.$from;
              const pos = $from.pos;

              // Find the card depth in the resolved position
              let cardDepth = -1;
              for (let d = $from.depth; d >= 0; d--) {
                if ($from.node(d).type.name === TIPTAP_CARD_TYPE) {
                  cardDepth = d;
                  break;
                }
              }

              if (cardDepth < 0) {
                return false;
              }

              // If the cursor is inside CARD_HEADER or CARD_FOOTER, redirect
              // the split to the wrapper's outer boundary so the wrapper stays
              // intact in one of the resulting cards (splitting through it
              // would produce schema-invalid cards).
              const wrapperRedirect = redirectSplitForCardWrapper(tr, $from, cardDepth);
              if (wrapperRedirect) {
                if (dispatch) {
                  dispatch(tr.scrollIntoView());
                }
                return true;
              }

              const blockDepth = cardDepth + 2;
              const blockNode = $from.depth >= blockDepth ? $from.node(blockDepth) : null;

              // Preserve the original cursor-split behavior for direct text
              // blocks in CARD_CONTENT. This keeps Mod-Enter at the end of a
              // paragraph creating a new empty card via the textblock split,
              // while nested text inside atomic blocks like LAYOUT/TABLE still
              // goes through the explicit block-target logic below.
              if (blockNode?.isTextblock && $from.depth === blockDepth) {
                const splitDepth = $from.depth - cardDepth + 1;

                if (dispatch) {
                  if (!splitCardTransaction(tr, { splitPos: pos, splitDepth })) {
                    return false;
                  }
                  tr.scrollIntoView();
                  dispatch(tr);
                }

                return true;
              }

              const cardStart = $from.start(cardDepth);
              const cardNode = $from.node(cardDepth);
              const splitTarget = getCardSplitTargetAtPos($from, pos, cardDepth);
              if (!splitTarget) {
                const boundaryRedirect = redirectSplitForCardChildBoundary(tr, $from, cardDepth);
                if (boundaryRedirect) {
                  if (dispatch) {
                    dispatch(tr.scrollIntoView());
                  }
                  return true;
                }
                return false;
              }

              const { splitPos } = splitTarget;
              const splitBoundaryRedirect = redirectSplitForCardChildBoundary(
                tr,
                tr.doc.resolve(splitPos),
                cardDepth
              );
              if (splitBoundaryRedirect) {
                if (dispatch) {
                  dispatch(tr.scrollIntoView());
                }
                return true;
              }

              const posInCard = splitPos - cardStart;
              if (posInCard <= 0 || posInCard >= cardNode.content.size) {
                return false;
              }

              if (dispatch) {
                if (!splitCardTransaction(tr, splitTarget)) {
                  return false;
                }
                tr.scrollIntoView();
                dispatch(tr);
              }

              return true;
            },
          splitCardAtPos:
            (pos: number) =>
            ({ tr, dispatch, state }) => {
              const $pos = state.doc.resolve(pos);

              let cardDepth = -1;
              for (let d = $pos.depth; d >= 0; d--) {
                if ($pos.node(d).type.name === TIPTAP_CARD_TYPE) {
                  cardDepth = d;
                  break;
                }
              }

              if (cardDepth < 0) {
                return false;
              }

              // Inside CARD_HEADER / CARD_FOOTER: see the matching redirect in
              // `splitCard` above.
              const wrapperRedirect = redirectSplitForCardWrapper(tr, $pos, cardDepth);
              if (wrapperRedirect) {
                if (dispatch) {
                  dispatch(tr.scrollIntoView());
                }
                return true;
              }

              const cardStart = $pos.start(cardDepth);
              const cardNode = $pos.node(cardDepth);

              const splitTarget = getCardSplitTargetAtPos($pos, pos, cardDepth);
              if (!splitTarget) {
                // Position is at the boundary between CARD children rather than
                // inside CARD_CONTENT. Detach a header/footer wrapper into a
                // sibling CARD so the split still succeeds without violating
                // the CARD schema.
                const boundaryRedirect = redirectSplitForCardChildBoundary(tr, $pos, cardDepth);
                if (boundaryRedirect) {
                  if (dispatch) {
                    dispatch(tr.scrollIntoView());
                  }
                  return true;
                }

                return false;
              }
              const { splitPos } = splitTarget;

              // A split target computed from inside CARD_CONTENT can still land
              // on the CARD's direct CONTENT|FOOTER or HEADER|CONTENT boundary.
              // Redirect those through the wrapper move instead of letting a
              // plain `tr.split` produce a CARD with an empty CARD_CONTENT.
              const boundaryRedirect = redirectSplitForCardChildBoundary(
                tr,
                tr.doc.resolve(splitPos),
                cardDepth
              );
              if (boundaryRedirect) {
                if (dispatch) {
                  dispatch(tr.scrollIntoView());
                }
                return true;
              }

              // Don't split if it would create an empty card
              const posInCard = splitPos - cardStart;
              if (posInCard <= 0 || posInCard >= cardNode.content.size) {
                return false;
              }

              if (dispatch) {
                if (!splitCardTransaction(tr, splitTarget)) {
                  return false;
                }
                tr.scrollIntoView();
                dispatch(tr);
              }

              return true;
            },
          mergeCardWithNext:
            (cardIndex: number) =>
            ({ state, dispatch }) => {
              const target = findCardAtIndex(state.doc, cardIndex);
              if (!target) {
                return false;
              }

              const { node: targetNode, pos: targetPos } = target;
              const nextCardPos = targetPos + targetNode.nodeSize;
              const nextNode = state.doc.nodeAt(nextCardPos);
              if (!nextNode || nextNode.type.name !== TIPTAP_CARD_TYPE) {
                return false;
              }

              if (!dispatch) {
                return true;
              }

              const tr = state.tr;

              // CARD's content schema is `CARD_HEADER? CARD_CONTENT CARD_FOOTER?`.
              // A naive depth-2 join would produce invalid structures whenever:
              //  - the first card has a CARD_FOOTER (it'd end up before the
              //    second card's CARD_CONTENT), or
              //  - the second card has a CARD_HEADER (it'd end up after the
              //    first card's CARD_CONTENT).
              // Demote those wrappers — strip the layout's banner attribute
              // and move the bare layout into the matching CARD_CONTENT
              // (footer → end of first's content, header → start of second's
              // content) — so the layout content survives the merge.
              demoteCardWrapper(tr, nextNode.attrs.id, TIPTAP_CARD_HEADER_TYPE, 'start');
              demoteCardWrapper(tr, targetNode.attrs.id, TIPTAP_CARD_FOOTER_TYPE, 'end');

              // After the demotions, the boundary between the two cards has
              // shifted. Use the mapped `nextCardPos` to locate it.
              const mappedNextCardPos = tr.mapping.map(nextCardPos);

              // Join the two CARDs at depth 2 so their inner CARD_CONTENT
              // children are also merged into a single content node. This
              // preserves block structure inside CARD_CONTENT and is the
              // clean inverse of splitCardAtPos for block-boundary splits.
              dispatch(tr.join(mappedNextCardPos, 2).scrollIntoView());
              return true;
            },
        };
      },

      addKeyboardShortcuts() {
        return {
          Backspace: () => {
            const { state } = this.editor;
            const { selection } = state;

            // Backspace at the start of an empty cell inside a CARD_HEADER /
            // CARD_FOOTER banner — when the banner has no content anywhere,
            // detach it (clears the wrapper, layout becomes regular).
            // Without this, Backspace is a no-op because the schema prevents
            // merging across the wrapper boundary.
            if (selection.empty && selection.$from.parentOffset === 0) {
              const detached = detachEmptyBannerOnBackspace(this.editor);
              if (detached) {
                return true;
              }
            }

            const cardNode = findParentNode(node => node.type.name === TIPTAP_CARD_TYPE)(selection);

            if (!cardNode) {
              return false;
            }

            // Check if card content is a single empty paragraph (no footer)
            const { node } = cardNode;
            const cardContent = node.firstChild;
            const isEmptyCard =
              node.childCount === 1 &&
              cardContent?.type.name === TIPTAP_CARD_CONTENT_TYPE &&
              cardContent.childCount === 1 &&
              cardContent.firstChild?.isTextblock &&
              cardContent.firstChild.content.size === 0;

            if (!isEmptyCard) {
              return false;
            }

            // Count cards and find the index of the current card by position
            let cardCount = 0;
            let cardIndex = -1;
            state.doc.descendants((n, pos) => {
              if (n.type.name === TIPTAP_CARD_TYPE) {
                if (pos === cardNode.pos) {
                  cardIndex = cardCount;
                }
                cardCount++;
                return false;
              }
            });

            // Don't delete the last remaining card
            if (cardCount <= 1 || cardIndex === -1) {
              return false;
            }

            return this.editor.commands.deleteCard(cardIndex);
          },
          'Mod-Enter': () => this.editor.commands.splitCard(),
        };
      },

      addProseMirrorPlugins() {
        const plugins = [createCardNormalizingTransactionPlugin(), createCardPastePlugin()];
        const getCardsApi = this.options.getCardsApi;
        const services = this.options._services;
        const formats: CardFormat[] = this.options.formats ?? [];
        const initialPageFormat: string | undefined = this.options.initialPageFormat;

        // Initialize storage from config
        const storage = this.editor.storage[TIPTAP_CARD_TYPE] as CardExtensionStorage;
        storage.formats = formats;
        if (initialPageFormat) {
          storage.activePageFormat = formats.find(f => f.name === initialPageFormat);
        }

        if (getCardsApi && services) {
          plugins.push(
            createCardsApiPlugin({
              getCardsApi,
              editor: this.editor,
              services,
              formats,
            })
          );
        }
        return plugins;
      },
    };
  },
});

/**
 * True iff every direct cell of `layoutNode` contains nothing but empty
 * textblocks. Used to decide whether a Backspace at the start of an empty
 * banner cell should detach the banner without destroying real content.
 */
const isBannerLayoutEmpty = (layoutNode: ProseMirrorNode): boolean => {
  let allEmpty = true;
  layoutNode.content.forEach(cell => {
    cell.content.forEach(child => {
      if (!child.isTextblock || child.content.size > 0) {
        allEmpty = false;
      }
    });
  });
  return allEmpty;
};

/**
 * Handle Backspace at the start of an empty cell that lives inside a
 * `CARD_HEADER` or `CARD_FOOTER` banner. The schema prevents merging across
 * the wrapper boundary, so a plain Backspace is a no-op and the user is
 * stuck. When the banner's cells are all empty, the natural intent is "I
 * emptied the banner; remove it" — invoke `setLayoutBanner` with
 * `undefined` to demote the layout back into `CARD_CONTENT` (or strip the
 * banner attr at doc level). Returns `true` if the case was handled so the
 * Backspace shortcut can stop here.
 */
const detachEmptyBannerOnBackspace = (editor: Editor): boolean => {
  const $from = editor.state.selection.$from;
  if (!$from.parent.isTextblock || $from.parent.content.size > 0) {
    return false;
  }

  for (let d = $from.depth - 1; d > 0; d--) {
    const node = $from.node(d);
    if (node.type.name !== TIPTAP_LAYOUT_TYPE) {
      continue;
    }
    const parentName = $from.node(d - 1).type.name;
    const isBannerWrapper =
      parentName === TIPTAP_CARD_HEADER_TYPE || parentName === TIPTAP_CARD_FOOTER_TYPE;
    if (!isBannerWrapper || !isBannerLayoutEmpty(node)) {
      return false;
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (editor.commands as any).setLayoutBanner(node.attrs.id, undefined);
  }
  return false;
};

/**
 * Splitting through a CARD_HEADER or CARD_FOOTER ancestor would produce two
 * cards each missing CARD_CONTENT — schema-invalid, and splitting a banner
 * across pages isn't meaningful UX anyway. Instead, when the cursor sits
 * inside one of those wrappers, detach the wrapper from its card and place
 * it in a fresh sibling CARD. CARD's required CARD_CONTENT is auto-filled
 * via `createAndFill`, which a plain `tr.split` cannot do.
 *  - Inside CARD_FOOTER → footer moves to a new card *after* the original.
 *  - Inside CARD_HEADER → header moves to a new card *before* the original.
 *
 * Mutates `tr` and returns `true` on a hit so the caller can dispatch and
 * skip its own split logic.
 */
const redirectSplitForCardWrapper = (
  tr: Transaction,
  $pos: ResolvedPos,
  cardDepth: number
): boolean => {
  for (let d = $pos.depth; d > cardDepth; d--) {
    const wrapperNode = $pos.node(d);
    const name = wrapperNode.type.name;
    if (name !== TIPTAP_CARD_HEADER_TYPE && name !== TIPTAP_CARD_FOOTER_TYPE) {
      continue;
    }

    const cardType = tr.doc.type.schema.nodes[TIPTAP_CARD_TYPE];
    // createAndFill adds the schema-required CARD_CONTENT next to the
    // wrapper so the new sibling CARD is valid (HEADER? CONTENT FOOTER?).
    const newCard = cardType.createAndFill(null, wrapperNode);
    if (!newCard) {
      return false;
    }

    const wrapperFromPos = $pos.before(d);
    const cardOuterPos =
      name === TIPTAP_CARD_FOOTER_TYPE ? $pos.after(cardDepth) : $pos.before(cardDepth);

    return moveCardWrapperToSibling(tr, wrapperNode, wrapperFromPos, cardOuterPos, newCard);
  }
  return false;
};

const isListNode = (node: ProseMirrorNode): boolean =>
  node.type.name === Node_Type.BULLETED_LIST || node.type.name === Node_Type.ORDERED_LIST;

const getItemsBeforeListSplit = (
  listNode: ProseMirrorNode,
  listStart: number,
  splitPos: number
) => {
  let itemsBeforeSplit = 0;
  listNode.forEach((_child, offset) => {
    if (listStart + offset < splitPos) {
      itemsBeforeSplit++;
    }
  });
  return itemsBeforeSplit;
};

const getTargetListDepth = ($pos: ResolvedPos, topListDepth: number): number | undefined => {
  for (let depth = $pos.depth; depth >= topListDepth; depth--) {
    if (
      isListNode($pos.node(depth)) &&
      (depth === $pos.depth || $pos.node(depth + 1)?.type.name === Node_Type.LIST_ITEM)
    ) {
      return depth;
    }
  }
  return undefined;
};

const getListVisibleOffset = (
  $pos: ResolvedPos,
  topListDepth: number,
  targetListDepth: number
): number => {
  let offset = 0;
  let listCount = 0;

  for (let depth = topListDepth; depth <= targetListDepth; depth++) {
    const node = $pos.node(depth);
    if (isListNode(node)) {
      offset += node.attrs.offset ?? 0;
      listCount++;
    }
  }

  return offset + Math.max(0, listCount - 1);
};

const getTrailingNestedListSplitTarget = (
  $pos: ResolvedPos,
  cardDepth: number,
  topListDepth: number,
  topListNode: ProseMirrorNode,
  topListItemIndex: number
): CardSplitTarget | undefined => {
  let topListItem: ProseMirrorNode | undefined;
  let topListItemPos = -1;
  topListNode.forEach((child, offset, index) => {
    if (index === topListItemIndex) {
      topListItem = child;
      topListItemPos = $pos.start(topListDepth) + offset;
    }
  });

  if (!topListItem || topListItemPos === -1) {
    return undefined;
  }

  let targetListNode: ProseMirrorNode | undefined;
  let targetListIndex = -1;
  let targetListOffsetInTopItem = -1;
  topListItem.forEach((child, offset, index) => {
    if (isListNode(child)) {
      targetListNode = child;
      targetListIndex = index;
      targetListOffsetInTopItem = offset;
    }
  });

  if (!targetListNode || targetListIndex <= 0) {
    return undefined;
  }

  return {
    splitPos: topListItemPos + 1 + targetListOffsetInTopItem,
    splitDepth: 1,
    nestedListSplit: {
      cardPos: $pos.before(cardDepth),
      cardContentPos: $pos.before(cardDepth + 1),
      topListPos: $pos.before(topListDepth),
      topListItemIndex,
      targetListPos: topListItemPos + 1 + targetListOffsetInTopItem,
      targetListOffsetInTopItem,
      itemsBeforeSplit: 0,
      continuationOffset: (topListNode.attrs.offset ?? 0) + (targetListNode.attrs.offset ?? 0) + 1,
      ...(topListNode.type.name === Node_Type.ORDERED_LIST
        ? { outerOrderedListStart: topListNode.attrs.start + topListItemIndex + 1 }
        : {}),
    },
    ...(targetListNode.type.name === Node_Type.ORDERED_LIST
      ? { orderedListStart: targetListNode.attrs.start }
      : {}),
  };
};

const isAtEndOfDeepNestedBranch = (
  $pos: ResolvedPos,
  directListDepth: number,
  targetListDepth: number,
  itemsBeforeSplit: number
): boolean => {
  if (itemsBeforeSplit !== $pos.node(targetListDepth).childCount) {
    return false;
  }

  for (let depth = targetListDepth - 1; depth > directListDepth; depth -= 2) {
    if ($pos.index(depth) !== $pos.node(depth).childCount - 1) {
      return false;
    }
  }

  return true;
};

const getDeepNestedListEndSplitTarget = (
  $pos: ResolvedPos,
  cardDepth: number,
  topListDepth: number,
  targetListDepth: number,
  itemsBeforeSplit: number
): CardSplitTarget | undefined => {
  const directListDepth = topListDepth + 2;
  if (
    targetListDepth <= directListDepth ||
    !isListNode($pos.node(directListDepth)) ||
    !isAtEndOfDeepNestedBranch($pos, directListDepth, targetListDepth, itemsBeforeSplit)
  ) {
    return undefined;
  }

  const topListNode = $pos.node(topListDepth);
  const topListItemDepth = topListDepth + 1;
  const topListItemPos = $pos.before(topListItemDepth);
  const topListItemIndex = getItemsBeforeListSplit(
    topListNode,
    $pos.start(topListDepth),
    topListItemPos
  );
  const directListNode = $pos.node(directListDepth);
  const directListItemsBeforeSplit = $pos.index(directListDepth) + 1;
  const directListPos = $pos.before(directListDepth);

  return {
    splitPos: $pos.after(directListDepth + 1),
    splitDepth: 1,
    nestedListSplit: {
      cardPos: $pos.before(cardDepth),
      cardContentPos: $pos.before(cardDepth + 1),
      topListPos: $pos.before(topListDepth),
      topListItemIndex,
      targetListPos: directListPos,
      targetListOffsetInTopItem: directListPos - (topListItemPos + 1),
      itemsBeforeSplit: directListItemsBeforeSplit,
      continuationOffset: getListVisibleOffset($pos, topListDepth, directListDepth),
      ...(topListNode.type.name === Node_Type.ORDERED_LIST
        ? { outerOrderedListStart: topListNode.attrs.start + topListItemIndex + 1 }
        : {}),
    },
    ...(directListNode.type.name === Node_Type.ORDERED_LIST
      ? { orderedListStart: directListNode.attrs.start + directListItemsBeforeSplit }
      : {}),
  };
};

const getListItemSplitTargetAtPos = (
  $pos: ResolvedPos,
  pos: number,
  cardDepth: number,
  topListDepth: number
): CardSplitTarget | undefined => {
  const targetListDepth = getTargetListDepth($pos, topListDepth);
  if (targetListDepth === undefined) {
    return undefined;
  }

  const listNode = $pos.node(targetListDepth);
  const isAtListChildBoundary = $pos.depth === targetListDepth;
  const listItemDepth = targetListDepth + 1;
  const isAtListItemEnd = !isAtListChildBoundary && pos >= $pos.end(listItemDepth) - 1;
  const splitPos = isAtListChildBoundary
    ? pos
    : isAtListItemEnd
      ? $pos.after(listItemDepth)
      : $pos.before(listItemDepth);
  const itemsBeforeSplit = isAtListChildBoundary
    ? $pos.index(targetListDepth)
    : getItemsBeforeListSplit(listNode, $pos.start(targetListDepth), splitPos);

  if (isAtListChildBoundary && targetListDepth === topListDepth && itemsBeforeSplit > 0) {
    const trailingNestedListSplitTarget = getTrailingNestedListSplitTarget(
      $pos,
      cardDepth,
      topListDepth,
      listNode,
      itemsBeforeSplit - 1
    );
    if (trailingNestedListSplitTarget) {
      return trailingNestedListSplitTarget;
    }
  }

  if (targetListDepth > topListDepth) {
    const deepNestedListEndSplitTarget = getDeepNestedListEndSplitTarget(
      $pos,
      cardDepth,
      topListDepth,
      targetListDepth,
      itemsBeforeSplit
    );
    if (deepNestedListEndSplitTarget) {
      return deepNestedListEndSplitTarget;
    }

    const topListNode = $pos.node(topListDepth);
    const topListItemDepth = topListDepth + 1;
    const topListItemPos = $pos.before(topListItemDepth);
    const topListItemIndex = getItemsBeforeListSplit(
      topListNode,
      $pos.start(topListDepth),
      topListItemPos
    );

    return {
      splitPos,
      splitDepth: 1,
      nestedListSplit: {
        cardPos: $pos.before(cardDepth),
        cardContentPos: $pos.before(cardDepth + 1),
        topListPos: $pos.before(topListDepth),
        topListItemIndex,
        targetListPos: $pos.before(targetListDepth),
        targetListOffsetInTopItem: $pos.before(targetListDepth) - (topListItemPos + 1),
        itemsBeforeSplit,
        continuationOffset: getListVisibleOffset($pos, topListDepth, targetListDepth),
        ...(topListNode.type.name === Node_Type.ORDERED_LIST
          ? { outerOrderedListStart: topListNode.attrs.start + topListItemIndex + 1 }
          : {}),
      },
      ...(listNode.type.name === Node_Type.ORDERED_LIST
        ? { orderedListStart: listNode.attrs.start + itemsBeforeSplit }
        : {}),
    };
  }

  if (itemsBeforeSplit === 0) {
    return {
      splitPos: $pos.before(targetListDepth),
      splitDepth: 2,
      listSplit: {
        cardPos: $pos.before(cardDepth),
        cardContentPos: $pos.before(cardDepth + 1),
        listPos: $pos.before(topListDepth),
        itemsBeforeSplit,
      },
    };
  }

  if (itemsBeforeSplit === listNode.childCount) {
    return {
      splitPos: $pos.after(targetListDepth),
      splitDepth: 2,
      listSplit: {
        cardPos: $pos.before(cardDepth),
        cardContentPos: $pos.before(cardDepth + 1),
        listPos: $pos.before(topListDepth),
        itemsBeforeSplit,
      },
    };
  }

  return {
    splitPos,
    splitDepth: 1,
    listSplit: {
      cardPos: $pos.before(cardDepth),
      cardContentPos: $pos.before(cardDepth + 1),
      listPos: $pos.before(topListDepth),
      itemsBeforeSplit,
    },
    ...(listNode.type.name === Node_Type.ORDERED_LIST
      ? { orderedListStart: listNode.attrs.start + itemsBeforeSplit }
      : {}),
  };
};

export const getCardSplitTargetAtPos = (
  $pos: ResolvedPos,
  pos: number,
  cardDepth: number
): CardSplitTarget | undefined => {
  // Block-level child is nested under CARD_CONTENT (cardDepth + 1).
  const blockDepth = cardDepth + 2;

  if ($pos.depth === blockDepth - 1) {
    // Boundary between sibling blocks inside CARD_CONTENT
    // (e.g., before/after a DIVIDER, LAYOUT, or other non-text block).
    return {
      splitPos: pos,
      splitDepth: 2,
    };
  }

  const childNode = $pos.depth >= blockDepth ? $pos.node(blockDepth) : null;
  if (!childNode) {
    return undefined;
  }

  if (isListNode(childNode)) {
    const listItemSplitTarget = getListItemSplitTargetAtPos($pos, pos, cardDepth, blockDepth);
    if (listItemSplitTarget) {
      return listItemSplitTarget;
    }
  }

  const isInTextBlock = childNode.isTextblock;
  const offsetInBlock = pos - $pos.start(blockDepth);
  const atBlockStart = offsetInBlock === 0;
  const atBlockEnd = offsetInBlock === childNode.content.size;

  if (isInTextBlock && !atBlockStart && !atBlockEnd) {
    // Inside a text block — split at the cursor through all levels.
    return {
      splitPos: pos,
      splitDepth: $pos.depth - cardDepth + 1,
    };
  }

  if (!isInTextBlock) {
    // Non-text container blocks like LAYOUT / TABLE are treated as atomic:
    // if the sampled position lands anywhere inside them, split above by
    // default; only the block's last internal position maps to a split below.
    return {
      splitPos: atBlockEnd ? $pos.after(blockDepth) : $pos.before(blockDepth),
      splitDepth: 2,
    };
  }

  if (atBlockEnd) {
    // At the end of a text block — split right after it.
    return {
      splitPos: $pos.after(blockDepth),
      splitDepth: 2,
    };
  }

  if (atBlockStart) {
    // At the start of a text block — split right before it.
    return {
      splitPos: $pos.before(blockDepth),
      splitDepth: 2,
    };
  }

  return undefined;
};

/**
 * A click on the visual page boundary can resolve to the boundary between the
 * CARD's direct children instead of a block boundary inside CARD_CONTENT:
 *  - HEADER | CONTENT
 *  - CONTENT | FOOTER
 *
 * Those positions can't be handled with a plain `tr.split` because CARD's
 * schema requires CARD_CONTENT. Mirror the wrapper redirect above by moving
 * the adjacent header/footer wrapper into a fresh sibling CARD.
 */
export const redirectSplitForCardChildBoundary = (
  tr: Transaction,
  $pos: ResolvedPos,
  cardDepth: number
): boolean => {
  const cardNode = $pos.node(cardDepth);
  const cardStart = $pos.start(cardDepth);
  const boundaryOffset = $pos.pos - cardStart;

  if (boundaryOffset <= 0 || boundaryOffset >= cardNode.content.size) {
    return false;
  }

  let beforeBoundary: { node: ProseMirrorNode; pos: number } | undefined;
  let afterBoundary: { node: ProseMirrorNode; pos: number } | undefined;

  cardNode.forEach((child, offset) => {
    const childPos = cardStart + offset;
    if (!beforeBoundary && offset + child.nodeSize === boundaryOffset) {
      beforeBoundary = { node: child, pos: childPos };
    }
    if (!afterBoundary && offset === boundaryOffset) {
      afterBoundary = { node: child, pos: childPos };
    }
  });

  if (beforeBoundary?.node.type.name === TIPTAP_CARD_HEADER_TYPE) {
    return moveCardWrapperToSibling(
      tr,
      beforeBoundary.node,
      beforeBoundary.pos,
      $pos.before(cardDepth)
    );
  }

  if (afterBoundary?.node.type.name === TIPTAP_CARD_FOOTER_TYPE) {
    return moveCardWrapperToSibling(
      tr,
      afterBoundary.node,
      afterBoundary.pos,
      $pos.after(cardDepth)
    );
  }

  return false;
};

const moveCardWrapperToSibling = (
  tr: Transaction,
  wrapperNode: ProseMirrorNode,
  wrapperPos: number,
  cardOuterPos: number,
  newCard = tr.doc.type.schema.nodes[TIPTAP_CARD_TYPE].createAndFill(null, wrapperNode)
): boolean => {
  if (!newCard) {
    return false;
  }

  tr.delete(wrapperPos, wrapperPos + wrapperNode.nodeSize);
  tr.insert(tr.mapping.map(cardOuterPos), newCard);
  return true;
};

const splitCardTransaction = (tr: Transaction, splitTarget: CardSplitTarget): boolean => {
  if (splitTarget.listSplit) {
    return splitCardAtListItem(tr, splitTarget);
  }

  if (splitTarget.nestedListSplit) {
    return splitCardAtNestedListItem(tr, splitTarget);
  }

  try {
    tr.split(splitTarget.splitPos, splitTarget.splitDepth);
    return true;
  } catch {
    return false;
  }
};

const getNodeChildren = (node: ProseMirrorNode): ProseMirrorNode[] => {
  const children: ProseMirrorNode[] = [];
  node.forEach(child => children.push(child));
  return children;
};

const createListWithChildren = (
  listNode: ProseMirrorNode,
  children: ProseMirrorNode[],
  attrs = listNode.attrs
): ProseMirrorNode => listNode.type.create(attrs, Fragment.fromArray(children));

const createListWithChildrenIfAny = (
  listNode: ProseMirrorNode,
  children: ProseMirrorNode[],
  attrs = listNode.attrs
): ProseMirrorNode | undefined =>
  children.length > 0 ? createListWithChildren(listNode, children, attrs) : undefined;

const createNestedContinuationSibling = (
  topListNode: ProseMirrorNode,
  child: ProseMirrorNode
): ProseMirrorNode => {
  if (!isListNode(child)) {
    return child;
  }

  return createListWithChildren(child, getNodeChildren(child), {
    ...child.attrs,
    offset: (topListNode.attrs.offset ?? 0) + (child.attrs.offset ?? 0) + 1,
  });
};

const splitCardAtListItem = (tr: Transaction, splitTarget: CardSplitTarget): boolean => {
  const listSplit = splitTarget.listSplit;
  if (!listSplit) {
    return false;
  }

  const cardNode = tr.doc.nodeAt(listSplit.cardPos);
  const cardContentNode = tr.doc.nodeAt(listSplit.cardContentPos);
  const listNode = tr.doc.nodeAt(listSplit.listPos);

  if (!cardNode || !cardContentNode || !listNode) {
    return false;
  }

  const cardChildren = getNodeChildren(cardNode);
  const cardContentIndex = cardChildren.findIndex(child => child === cardContentNode);
  const cardContentChildren = getNodeChildren(cardContentNode);
  const listIndex = cardContentChildren.findIndex(child => child === listNode);

  if (cardContentIndex === -1 || listIndex === -1) {
    return false;
  }

  const listChildren = getNodeChildren(listNode);
  const beforeList = createListWithChildrenIfAny(
    listNode,
    listChildren.slice(0, listSplit.itemsBeforeSplit)
  );
  const afterListAttrs =
    splitTarget.orderedListStart === undefined
      ? listNode.attrs
      : { ...listNode.attrs, start: splitTarget.orderedListStart };
  const afterList = createListWithChildrenIfAny(
    listNode,
    listChildren.slice(listSplit.itemsBeforeSplit),
    afterListAttrs
  );
  const firstContentChildren = [
    ...cardContentChildren.slice(0, listIndex),
    ...(beforeList ? [beforeList] : []),
  ];
  const secondContentChildren = [
    ...(afterList ? [afterList] : []),
    ...cardContentChildren.slice(listIndex + 1),
  ];

  if (firstContentChildren.length === 0 || secondContentChildren.length === 0) {
    return false;
  }

  const firstContent = cardContentNode.type.create(
    cardContentNode.attrs,
    Fragment.fromArray(firstContentChildren)
  );
  const secondContent = cardContentNode.type.create(
    cardContentNode.attrs,
    Fragment.fromArray(secondContentChildren)
  );

  const firstCard = cardNode.type.create(
    cardNode.attrs,
    Fragment.fromArray([...cardChildren.slice(0, cardContentIndex), firstContent])
  );
  const secondCard = cardNode.type.create(
    cardNode.attrs,
    Fragment.fromArray([secondContent, ...cardChildren.slice(cardContentIndex + 1)])
  );

  tr.replaceWith(
    listSplit.cardPos,
    listSplit.cardPos + cardNode.nodeSize,
    Fragment.fromArray([firstCard, secondCard])
  );
  return true;
};

const splitCardAtNestedListItem = (tr: Transaction, splitTarget: CardSplitTarget): boolean => {
  const listSplit = splitTarget.nestedListSplit;
  if (!listSplit) {
    return false;
  }

  const cardNode = tr.doc.nodeAt(listSplit.cardPos);
  const cardContentNode = tr.doc.nodeAt(listSplit.cardContentPos);
  const topListNode = tr.doc.nodeAt(listSplit.topListPos);
  const targetListNode = tr.doc.nodeAt(listSplit.targetListPos);

  if (!cardNode || !cardContentNode || !topListNode || !targetListNode) {
    return false;
  }

  const cardChildren = getNodeChildren(cardNode);
  const cardContentIndex = cardChildren.findIndex(child => child === cardContentNode);
  const cardContentChildren = getNodeChildren(cardContentNode);
  const topListIndex = cardContentChildren.findIndex(child => child === topListNode);
  const topListChildren = getNodeChildren(topListNode);
  const topListItem = topListChildren[listSplit.topListItemIndex];

  if (cardContentIndex === -1 || topListIndex === -1 || !topListItem) {
    return false;
  }

  const topListItemChildren = getNodeChildren(topListItem);
  let targetListIndex = -1;
  topListItem.forEach((child, offset, index) => {
    if (offset === listSplit.targetListOffsetInTopItem && child.type === targetListNode.type) {
      targetListIndex = index;
    }
  });

  if (targetListIndex === -1) {
    return false;
  }

  const targetListChildren = getNodeChildren(targetListNode);
  const beforeTargetList = createListWithChildrenIfAny(
    targetListNode,
    targetListChildren.slice(0, listSplit.itemsBeforeSplit)
  );
  const afterTargetListAttrs =
    splitTarget.orderedListStart === undefined
      ? { ...targetListNode.attrs, offset: listSplit.continuationOffset }
      : {
          ...targetListNode.attrs,
          offset: listSplit.continuationOffset,
          start: splitTarget.orderedListStart,
        };
  const afterTargetList = createListWithChildrenIfAny(
    targetListNode,
    targetListChildren.slice(listSplit.itemsBeforeSplit),
    afterTargetListAttrs
  );

  const firstTopListItemChildren = [
    ...topListItemChildren.slice(0, targetListIndex),
    ...(beforeTargetList ? [beforeTargetList] : []),
  ];
  const firstTopListItem = topListItem.type.create(
    topListItem.attrs,
    Fragment.fromArray(firstTopListItemChildren)
  );
  const firstTopList = createListWithChildren(topListNode, [
    ...topListChildren.slice(0, listSplit.topListItemIndex),
    firstTopListItem,
  ]);

  const secondContentChildren: ProseMirrorNode[] = [];
  if (afterTargetList) {
    secondContentChildren.push(afterTargetList);
  }
  secondContentChildren.push(
    ...topListItemChildren
      .slice(targetListIndex + 1)
      .map(child => createNestedContinuationSibling(topListNode, child))
  );
  const outerSuffixList = createListWithChildrenIfAny(
    topListNode,
    topListChildren.slice(listSplit.topListItemIndex + 1),
    listSplit.outerOrderedListStart === undefined
      ? topListNode.attrs
      : { ...topListNode.attrs, start: listSplit.outerOrderedListStart }
  );

  if (outerSuffixList) {
    secondContentChildren.push(outerSuffixList);
  }
  secondContentChildren.push(...cardContentChildren.slice(topListIndex + 1));

  if (secondContentChildren.length === 0) {
    return false;
  }

  const firstContent = cardContentNode.type.create(
    cardContentNode.attrs,
    Fragment.fromArray([...cardContentChildren.slice(0, topListIndex), firstTopList])
  );
  const secondContent = cardContentNode.type.create(
    cardContentNode.attrs,
    Fragment.fromArray(secondContentChildren)
  );

  const firstCard = cardNode.type.create(
    cardNode.attrs,
    Fragment.fromArray([...cardChildren.slice(0, cardContentIndex), firstContent])
  );
  const secondCard = cardNode.type.create(
    cardNode.attrs,
    Fragment.fromArray([secondContent, ...cardChildren.slice(cardContentIndex + 1)])
  );

  tr.replaceWith(
    listSplit.cardPos,
    listSplit.cardPos + cardNode.nodeSize,
    Fragment.fromArray([firstCard, secondCard])
  );
  return true;
};

/**
 * Demote a CARD_HEADER / CARD_FOOTER inside the card identified by `cardId`:
 *  - extract the layout it wraps,
 *  - strip the layout's `banner` attribute,
 *  - delete the wrapper itself,
 *  - re-insert the bare layout at the start (`'start'`) or end (`'end'`) of
 *    the card's CARD_CONTENT.
 *
 * No-op when the wrapper isn't present. Mutates `tr`.
 */
const demoteCardWrapper = (
  tr: Transaction,
  cardId: string,
  wrapperType: typeof TIPTAP_CARD_HEADER_TYPE | typeof TIPTAP_CARD_FOOTER_TYPE,
  insertAt: 'start' | 'end'
): void => {
  const card = findNodeById(tr, cardId)[0];
  if (!card) {
    return;
  }

  let wrapperPos = -1;
  let wrapperSize = -1;
  let layoutJson: Record<string, unknown> | undefined;
  card.node.forEach((child, offset) => {
    if (child.type.name !== wrapperType || wrapperPos !== -1) {
      return;
    }
    const layoutInside = child.firstChild;
    if (!layoutInside) {
      return;
    }
    wrapperPos = card.pos + 1 + offset;
    wrapperSize = child.nodeSize;
    const json = layoutInside.toJSON() as { attrs?: Record<string, unknown> };
    layoutJson = {
      ...json,
      attrs: { ...(json.attrs ?? {}), banner: undefined },
    };
  });
  if (wrapperPos === -1 || !layoutJson) {
    return;
  }

  tr.delete(wrapperPos, wrapperPos + wrapperSize);

  // Re-find the card after deletion — its position and content layout
  // shifted. Then locate the inner edge of CARD_CONTENT to insert at.
  const cardAfter = findNodeById(tr, cardId)[0];
  if (!cardAfter) {
    return;
  }

  let target = -1;
  cardAfter.node.forEach((child, offset) => {
    if (child.type.name !== TIPTAP_CARD_CONTENT_TYPE || target !== -1) {
      return;
    }
    const innerStart = cardAfter.pos + 1 + offset + 1;
    const innerEnd = cardAfter.pos + 1 + offset + child.nodeSize - 1;
    target = insertAt === 'start' ? innerStart : innerEnd;
  });
  if (target === -1) {
    return;
  }

  tr.insert(target, tr.doc.type.schema.nodeFromJSON(layoutJson));
};

const findCardAtIndex = (
  doc: ProseMirrorNode,
  cardIndex: number
): { node: ProseMirrorNode; pos: number } | undefined => {
  let currentCardIndex = 0;
  let result: { node: ProseMirrorNode; pos: number } | undefined;

  doc.forEach((node, offset) => {
    if (node.type.name !== TIPTAP_CARD_TYPE) {
      return;
    }

    if (currentCardIndex === cardIndex) {
      result = { node, pos: offset };
    }

    currentCardIndex++;
  });

  return result;
};
